    }
    nodeEntry.content.textContent = ToolBodyText(state, message);
    if (nodeEntry.spinner) {
      if (ToolShowsSpinner(state, message)) {
        nodeEntry.spinner.style.display = "";
      } else {
        nodeEntry.spinner.style.display = "none";
