  height: 100%;
  height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.sheaf-chat-screen
{
  display: flex;
  flex-direction: column;
  min-height: 100%;
  min-height: 100dvh;
}

.sheaf-chat-header
{
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  border-bottom: 1px solid var(--sheaf-chat-border);
  background: var(--sheaf-chat-surface);
