.sheaf-chat-icon-button
{
  width: var(--sheaf-chat-touch);
  padding: 0;
}

.sheaf-chat-back
{
  padding: 0 12px;
}

.sheaf-chat-button--primary
{
  background: var(--sheaf-chat-accent);
  border-color: transparent;
  color: #fff;
}

.sheaf-chat-button:disabled,
.sheaf-chat-icon-button:disabled
{
  opacity: 0.5;
  cursor: not-allowed;
}

.sheaf-chat-content
{
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 0;
}

.sheaf-chat-list
{
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 8px;
