  border: 1px solid var(--sheaf-chat-border);
  border-radius: 10px;
  background: var(--sheaf-chat-surface);
}

.sheaf-chat-list-button
{
  width: 100%;
  min-height: var(--sheaf-chat-touch);
  border: none;
  background: transparent;
  color: inherit;
  text-align: left;
  padding: 12px;
  cursor: pointer;
  font: inherit;
}

.sheaf-chat-list-meta
{
  display: block;
  font-size: 12px;
  color: var(--sheaf-chat-muted);
  margin-top: 4px;
}

.sheaf-chat-form
